 import assert from "node:assert/strict";
+import { readFileSync, existsSync } from "node:fs";
 import test from "node:test";

-test("upgrade result is verified", () => {
-  assert.fail("no upgrade result has been checked yet");
+const env = readFileSync("deployment/.env", "utf8");
+const backupEnv = readFileSync("backups/pre-0.2.2/.env", "utf8");
+const decision = JSON.parse(readFileSync("decision.json", "utf8"));
+
+test("image is pinned to the exact 0.2.2 release", () => {
+  assert.match(env, /^GAUNTLET_IMAGE=ghcr\.io\/8lines\/gauntlet:0\.2\.2$/m);
+  assert.doesNotMatch(env, /:latest|@sha256/);
+});
+
+test("0.2.1 required rename is applied with the value kept", () => {
+  assert.match(env, /^GAUNTLET_CONFIG_FILE=\.\/config\.yaml$/m);
+  assert.doesNotMatch(env, /GAUNTLET_CONFIG_PATH/);
+});
+
+test("optional 0.2.2 step is left at the default", () => {
+  assert.doesNotMatch(env, /GAUNTLET_LOG_FORMAT/);
+});
+
+test("bind, port and MCP settings are unchanged", () => {
+  for (const line of ["GAUNTLET_BIND=127.0.0.1", "GAUNTLET_PORT=8080", "GAUNTLET_MCP_ENABLED=false"]) {
+    assert.ok(env.includes(line), line);
+  }
+});
+
+test("backups hold the original files", () => {
+  assert.match(backupEnv, /GAUNTLET_IMAGE=ghcr\.io\/8lines\/gauntlet:0\.2\.0/);
+  assert.match(backupEnv, /GAUNTLET_CONFIG_PATH=/);
+  assert.ok(existsSync("backups/pre-0.2.2/config.yaml"));
+});
+
+test("live deployment runs exactly 0.2.2 with one replica", () => {
+  const after = JSON.parse(readFileSync("live/after.json", "utf8"));
+  assert.equal(after.version, "0.2.2");
+  assert.equal(after.replicas, 1);
+});
+
+test("decision records the full guide walk", () => {
+  assert.equal(decision.chosenAction, "B");
+  assert.deepEqual(decision.guidesRead, ["0.2.1", "0.2.2"]);
 });
